<?php declare(strict_types=1);
require dirname(__DIR__).'/native/bootstrap.php';
use Kulturhus\Native\TestSupport;
use Kulturhus\Native\Shared\{Access,Db};
use Kulturhus\Native\Cms\{Schema as CmsSchema,Pages,Media,HomeLayout};
use Kulturhus\Native\Language\{Schema,Settings,Translations,PublicResolver};
use Kulturhus\Native\Web\{Site,Cache,Articles,Gallery,PublishedLanguage};
$db=TestSupport::db();TestSupport::seed($db);CmsSchema::install($db);Schema::install($db);
$access=new Access($db,'admin');$pages=new Pages($db,$access);$translations=new Translations($db,$access);$settings=new Settings($db,$access);$resolver=new PublicResolver($db,$access);
$config=['source'=>'de','languages'=>[['code'=>'de','label'=>'Deutsch','enabled'=>true,'fallback'=>null,'messages'=>[]],['code'=>'en','label'=>'English','enabled'=>true,'fallback'=>'de','messages'=>[]]]];$settings->save($config,0);
$root=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/language-renderers';mkdir($root,0700);$media=new Media($db,$access,$root.'/media');
$image=imagecreatetruecolor(40,30);imagefill($image,0,0,imagecolorallocate($image,20,110,70));imagepng($image,$root.'/own.png');imagedestroy($image);$photo=$media->upload($root.'/own.png','own.png','Own original language renderer pixels');
$checks=0;
function check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException($label);++$checks;echo "PASS $label\n";}
function publishPage(array $data):array{global $pages;$page=$pages->save($data);return $pages->publish($page['id'],$page['version']);}
function translate(array $page,string $slug,array $fields):array{global $translations;$saved=$translations->save($page['id'],'en',['slug'=>$slug,'fields'=>$fields],$page['published_revision'],0);return $translations->publish($page['id'],'en',$saved['version']);}
function originalHash(PDO $db):string{$all=[];foreach(['khcms_pages','khcms_revisions','khcms_media','khcms_published_media','khcms_events','native_event_sources']as $table)$all[$table]=$db->query('SELECT * FROM '.$table.' ORDER BY 1,2')->fetchAll(PDO::FETCH_ASSOC);return hash('sha256',json_encode($all,JSON_THROW_ON_ERROR));}
function contains(string $html,string $needle,string $label):void{check(str_contains($html,$needle),$label);}
$containers=[];
foreach(['start'=>'Original home','aktuelles'=>'Original stories','galerie'=>'Original gallery','veranstaltungen'=>'Original programme','verein'=>'Original club','newsletter'=>'Original newsletter']as $slug=>$title)$containers[$slug]=publishPage(['title'=>$title,'slug'=>$slug,'excerpt'=>'Original introduction','body_html'=>'<p>Original container body</p>','nav_visible'=>true]+($slug==='start'?['home_layout'=>array_replace(HomeLayout::defaults(),['hero_title'=>'Original configured hero','hero_html'=>'<p>Original configured hero text</p>'])]:[]));
$story=publishPage(['title'=>'Original story title','slug'=>'aktuelles/language-story','template'=>'news','news_date'=>'2050-01-05','excerpt'=>'Original story introduction','body_html'=>'<p>Original <strong>story body</strong></p>','media_ids'=>[$photo['id']]]);
$fallback=publishPage(['title'=>'Original fallback story','slug'=>'aktuelles/language-fallback','template'=>'news','news_date'=>'2050-01-04','body_html'=>'<p>Original untranslated body</p>']);
$event=publishPage(['title'=>'Original concert title','slug'=>'veranstaltungen/language-concert','template'=>'event','event_start'=>'2050-01-12T20:00','event_location'=>'Original hall','excerpt'=>'Original event introduction','body_html'=>'<p>Original concert body</p>','media_ids'=>[$photo['id']]]);
$album=publishPage(['title'=>'Original album title','slug'=>'galerie/language-album','template'=>'gallery','excerpt'=>'Original album introduction','body_html'=>'<p>Original album body</p>','media_ids'=>[$photo['id']],'gallery_items'=>[['id'=>$photo['id'],'caption'=>'Original photo caption','tags'=>[]]]]);
for($index=0;$index<6;++$index)publishPage(['title'=>'Other original album '.$index,'slug'=>'galerie/language-extra-'.$index,'template'=>'gallery']);
foreach(['start'=>'home','aktuelles'=>'stories','galerie'=>'photos','veranstaltungen'=>'programme','verein'=>'club','newsletter'=>'newsletter']as $source=>$slug){$fields=['title'=>'English '.$slug,'excerpt'=>'English '.$slug.' introduction','body_html'=>'<p>English '.$slug.' container body</p>'];if($source==='start')$fields['home_layout']=['hero_title'=>'English configured hero','hero_html'=>'<p>English configured hero text</p>','poster_main'=>'COMMUNITY','events_heading'=>'English programme {jahr}','news_heading'=>'English latest stories'];translate($containers[$source],$slug,$fields);}
$storyTranslation=translate($story,'stories/english-story',['title'=>'English story title','excerpt'=>'English story introduction','body_html'=>'<p>English <strong>published story body</strong></p>']);
$eventTranslation=translate($event,'programme/english-concert',['title'=>'English concert title','excerpt'=>'English event introduction','body_html'=>'<p>English concert body</p>','event_location'=>'English hall']);
translate($album,'photos/english-album',['title'=>'English album title','excerpt'=>'English album introduction','body_html'=>'<p>English album body</p>']);
$draft=$pages->save(array_replace($story,['title'=>'DO NOT LEAK ORIGINAL DRAFT','body_html'=>'<p>DO NOT LEAK ORIGINAL DRAFT BODY</p>']),$story['version']);
$translations->save($story['id'],'en',['slug'=>'stories/private-new-url','fields'=>['title'=>'DO NOT LEAK TRANSLATION DRAFT','body_html'=>'<p>DO NOT LEAK TRANSLATION DRAFT BODY</p>']],$story['published_revision'],$storyTranslation['version']);
$eventDraft=$pages->save(array_replace($event,['title'=>'DO NOT LEAK EVENT DRAFT','body_html'=>'<p>DO NOT LEAK EVENT ORIGINAL DRAFT BODY</p>']),$event['version']);
$translations->save($event['id'],'en',['slug'=>'programme/private-new-event-url','fields'=>['title'=>'DO NOT LEAK EVENT TRANSLATION','body_html'=>'<p>DO NOT LEAK EVENT TRANSLATION BODY</p>']],$event['published_revision'],$eventTranslation['version']);
$before=originalHash($db);$pixels=hash_file('sha256',$media->variant($photo['id'],'original')['path']);
$site=new Site($pages,$media,new Cache($root.'/cache'),'https://example.invalid',$access->club(),new Gallery($db,$access,$root.'/media'),new Articles($db,$access,$root.'/media'),'/?view=website',['name'=>'Own synthetic language club'],null,$resolver);
$englishStory=$site->page('en/stories/english-story');
contains($englishStory,'English story title','translated article title reaches the actual site shell');
contains($englishStory,'English <strong>published story body</strong>','article body keeps the published translation instead of reloading original text');
contains($englishStory,'href="/site/en/stories"','article back links keep the current published language container');
check(!str_contains($englishStory,'Original <strong>story body')&&!str_contains($englishStory,'DO NOT LEAK'),'neither original body nor either private draft replaces the confirmed English story');
contains($site->page($story['slug']),'Original <strong>story body</strong>','source-language request still renders exact original body after an English request');
check($site->page('en/stories/english-story')===$englishStory,'one reused site object caches source and English responses separately');
$englishList=$site->page('en/stories');
contains($englishList,'English story title','news overview projects each actual publication into the requested language');
contains($englishList,'href="/site/en/stories/english-story"','news card opens the published translated story address');
contains($englishList,'Original fallback story','untranslated publication retains its real fallback title');
contains($englishList,'href="/site/en/aktuelles/language-fallback"','untranslated card keeps the selected language fallback route');
check(!str_contains($englishList,'DO NOT LEAK'),'news overview cannot expose newer private source or translation titles');
$programme=$site->page('en/programme',1,['q'=>'English concert','jahr'=>'2050']);
contains($programme,'English concert title','programme cards display current translated event titles');
contains($programme,'href="/site/en/programme/english-concert"','programme cards link to translated event details');
contains($programme,'action="/site/en/programme"','programme search and year form stay in the language container');
contains($programme,'value="English concert"','translated programme retains the actual supplied search query');
$emptyProgramme=$site->page('en/programme',1,['q'=>'No such original event']);
check(!str_contains($emptyProgramme,'<article class="event-row'),'translated programme passes filters through instead of caching an unfiltered page');
contains(html_entity_decode($emptyProgramme,ENT_QUOTES|ENT_HTML5,'UTF-8'),'Keine Veranstaltungen für diese Auswahl','translated programme displays its actual empty selection message');
$locationProgramme=$site->page('en/programme',1,['q'=>'English hall']);
contains($locationProgramme,'English concert title','programme search includes actually published translated locations');
$privateProgramme=$site->page('en/programme',1,['q'=>'DO NOT LEAK']);
check(!str_contains($privateProgramme,'<article class="event-row'),'programme search excludes private source and translation drafts');
$literalProgramme=$site->page('en/programme',1,['q'=>"%_' OR 1=1"]);
check(!str_contains($literalProgramme,'<article class="event-row'),'programme search treats SQL punctuation and wildcards literally');
$eventDetail=$site->page('en/programme/english-concert');
contains($eventDetail,'English concert body','translated event body reaches the actual detail renderer');
contains($eventDetail,'English hall','translated event location reaches detail rendering');
check(!str_contains($eventDetail,'DO NOT LEAK'),'event detail excludes both newer private source and translation drafts');
contains($eventDetail,'https://example.invalid/site/en/programme/english-concert','event structured data and canonical URL use the same translated address');
contains($eventDetail,'href="/site/en/programme"','event detail return link keeps the translated programme');
$gallery=$site->page('en/photos');
contains($gallery,'English photos','gallery container title uses its explicit translated title');
contains($gallery,'English album title','gallery overview resolves public translated album titles');
contains($gallery,'href="/site/en/photos/english-album"','album overview opens the confirmed translated album URL');
contains($gallery,'action="/site/en/photos#gallery-items"','gallery pagination preserves the selected language route');
$albumDetail=$site->page('en/photos/english-album');
contains($albumDetail,'English album body','album detail retains translated body content');
contains($albumDetail,'href="/site/en/photos"','album back link opens translated overview');
contains($albumDetail,'/media/'.$photo['id'].'/medium','translated album continues using its actual original public image');
$home=$site->page('en/home');
contains($home,'English configured hero','home hero projects configured translated layout text');
contains($home,'English configured hero text','home formatted hero text comes from a confirmed translation');
contains($home,'English concert title','home next-event card projects the actual public event');
contains($home,'href="/site/en/programme/english-concert"','home next-event card preserves translated target');
contains($home,'English story title','home latest stories project current translated titles');
contains($home,'href="/site/en/stories/english-story"','home latest story links preserve translated target');
contains($home,'href="/site/en/club"','home club action opens its confirmed translated page');
contains($home,'href="/site/en/newsletter"','home newsletter action opens the language route');
check(originalHash($db)===$before&&hash_file('sha256',$media->variant($photo['id'],'original')['path'])===$pixels,'all source page/revision/event/media records and original image bytes remain exact across localized rendering');
// Publication revocation must invalidate all renderer projections, not merely the direct detail URL.
$current=$translations->get($story['id'],'en');$translations->unpublish($story['id'],'en',$current['version']);
check($site->page('en/stories/english-story')===null,'withdrawn translated detail route cannot serve old cached story');
$after=$site->page('en/stories');
check(!str_contains($after,'English story title')&&str_contains($after,'Original story title'),'news overview immediately uses actual source fallback after translation withdrawal');
check(!str_contains($site->page('en/home'),'English story title'),'home latest stories immediately stops using revoked translated title');
$pages->unpublish($story['id'],$draft['version']);
check(!str_contains($site->page('en/stories'),'Original story title'),'withdrawn original disappears from translated listings instead of surviving as stale fallback');
$fresh=$pages->publicPage($event['slug']);$context=new PublishedLanguage($resolver,'en');$forged=$fresh;$forged['title']='DO NOT LEAK FORGED DTO';$projected=$context->page($forged);
check($projected['title']==='English concert title','projection rereads current public originals instead of trusting caller-provided text');
Db::run($db,"INSERT INTO native_event_sources(club_id,source,external_id,page_id,source_hash,state) VALUES(?,'facebook','own-language-concert',?,?,'cancelled')",[$access->club(),$event['id'],str_repeat('0',64)]);
Db::run($db,'UPDATE khcms_state SET generation=generation+1 WHERE club_id=?',[$access->club()]);
$cancelled=$site->page('en/programme/english-concert');
check(str_contains($cancelled,'English concert title')&&str_contains($cancelled,'Diese Veranstaltung wurde abgesagt.')&&str_contains($cancelled,'EventCancelled'),'translated event preserves the independently current provider cancellation and structured status');
Db::atomic($db,function()use($db,$access,$pages,$event,$eventDraft):void{
    $original=\Kulturhus\Native\Cms\EventIndex::capture($db,$access->club(),$event['id']);
    $withdrawn=$pages->unpublish($event['id'],$eventDraft['version']);
    \Kulturhus\Native\Cms\EventIndex::cancellation($db,$access->club(),$original,$withdrawn['version']);
});
$notice=$site->page($event['slug']);
check($notice!==null&&str_contains($notice,'Diese Veranstaltung wurde abgesagt.'),'existing public cancellation notice survives withdrawal of its source CMS publication');
$noticeList=$site->page('en/programme');
check(str_contains($noticeList,'Original concert title')&&str_contains($noticeList,'is-cancelled')&&str_contains($noticeList,'href="/site/'.$event['slug'].'"'),'translated programme keeps an actual cancellation notice with its retained original address');
$noticeSearch=$site->page('en/programme',1,['q'=>'Original concert']);
contains($noticeSearch,'Original concert title','notice search uses its actually retained original public text');
$staleNoticeSearch=$site->page('en/programme',1,['q'=>'English concert']);
check(!str_contains($staleNoticeSearch,'<article class="event-row'),'notice search cannot use translations detached from a withdrawn original publication');
$maximumSearch=$site->page('en/programme',1,['q'=>str_repeat('x',150)]);
check(!str_contains($maximumSearch,'<article class="event-row'),'localized programme retains the existing 150-character search limit');
$config['languages'][1]['enabled']=false;$settings->save($config,1);
check($site->page('en/home')===null&&$site->page('en/photos/english-album')===null,'disabling a language closes cached home and detail routes');
check($context->page($fresh)===null,'renderer context cannot reuse previously permitted language after revocation');
contains($site->page('start'),'Original configured hero','original home remains available after secondary language revocation');
echo json_encode(['suite'=>'native-language-renderers','checks'=>$checks,'live_transport'=>false],JSON_THROW_ON_ERROR)."\n";
